const email = $('When Called by Agent').first().json.email;

// If HTTP request failed (thanks to continueOnFail), catch it safely
const firstItem = $input.first()?.json;
if (!firstItem || firstItem.error || firstItem.code === 'woocommerce_rest_cannot_view') {
  return [{ json: { error: true, message: 'Could not retrieve orders at this time. Please try again later.' } }];
}

// n8n splits the WooCommerce array into multiple items.
const orders = $input.all().map(item => item.json);

if (!Array.isArray(orders) || orders.length === 0 || (orders.length === 1 && Object.keys(orders[0]).length === 0)) {
  return [{ json: { error: true, message: 'No orders were found for this email.' } }];
}

const emailLower = (email || '').trim().toLowerCase();
const matched = orders.filter(o => (o.billing?.email || '').trim().toLowerCase() === emailLower);

if (matched.length === 0) {
  return [{ json: { error: true, message: 'No orders were found for this email.' } }];
}

function extractMeta(metaArr, key) {
  const found = (metaArr || []).find(m => m.display_key === key || m.key === key);
  return found ? found.display_value || found.value : '';
}

const cleaned = matched.map(o => {
  const balanceFee = (o.fee_lines || []).find(f => (f.name || '').toLowerCase().includes('balance to pay on arrival'));
  const balanceDue = balanceFee ? Math.abs(parseFloat(balanceFee.amount || '0')).toFixed(2) : null;

  // Make response parser robust against missing/empty line_items
  const items = (o.line_items || []).map(li => ({
    service_name: extractMeta(li.meta_data, 'Tour') || li.name,
    pickup_location: extractMeta(li.meta_data, 'From'),
    pickup_date: extractMeta(li.meta_data, 'Pickup Date'),
    pickup_time: extractMeta(li.meta_data, 'Pickup Time'),
    passengers: extractMeta(li.meta_data, 'Passengers'),
    quantity: li.quantity,
    line_total: li.total
  }));

  return {
    order_id: o.id,
    order_number: o.number,
    status: o.status,
    date_created: o.date_created,
    payment_method: o.payment_method_title || o.payment_method,
    currency: o.currency,
    deposit_paid_now: o.total,
    balance_due_on_arrival: balanceDue,
    needs_payment: o.needs_payment,
    payment_url: o.payment_url,
    billing: {
      name: `${o.billing?.first_name || ''} ${o.billing?.last_name || ''}`.trim(),
      email: o.billing?.email,
      phone: o.billing?.phone,
      address: [o.billing?.address_1, o.billing?.city, o.billing?.state, o.billing?.postcode, o.billing?.country].filter(Boolean).join(', ')
    },
    items
  };
});

return [{
  json: {
    error: false,
    order_count: cleaned.length,
    orders: cleaned
  }
}];

